pous.declaration:
FUNCTION_BLOCK PumpAlternation
VAR_INPUT
    start : BOOL;
    stop : BOOL;
    pump1Feedback : BOOL;
    pump2Feedback : BOOL;
END_VAR
VAR_OUTPUT
    pump1Run : BOOL;
    pump2Run : BOOL;
END_VAR
VAR
    lead : INT := 1;
    startPrev : BOOL;
    startEdge : BOOL;
    switchTof : TOF;
END_VAR

pous.implementation:
startEdge := start AND NOT startPrev;
startPrev := start;
IF stop THEN
    pump1Run := FALSE;
    pump2Run := FALSE;
    lead := 1;
ELSIF startEdge THEN
    IF lead = 1 THEN
        pump1Run := TRUE;
        pump2Run := FALSE;
    ELSE
        pump1Run := FALSE;
        pump2Run := TRUE;
    END_IF
    lead := 3 - lead;
END_IF
switchTof(IN := (pump1Run AND NOT pump1Feedback) OR (pump2Run AND NOT pump2Feedback),
          PT := T#2s);
IF switchTof.Q THEN
    IF pump1Run THEN
        pump1Run := FALSE;
        pump2Run := TRUE;
    ELSIF pump2Run THEN
        pump2Run := FALSE;
        pump1Run := TRUE;
    END_IF
END_IF
